/* ゲーム本体＋初心者ガイド：広い画面は横並び、狭い画面はガイドを下へ */
#game-layout {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: center;
  gap: 12px;
  padding: 0 10px 20px;
  max-width: 1320px;
  margin: 0 auto;
}
#table-wrap {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 980px;
}
/* 右カラム：固定幅・縦スクロール（sticky でプレイ中も常に近くに） */
#beginner-panel {
  flex: 0 0 300px;
  width: 300px;
  max-width: 100%;
  align-self: flex-start;
  position: sticky;
  top: 8px;
  max-height: calc(100vh - 16px);
  overflow-y: auto;
  padding: 10px 12px;
  background: rgba(12, 24, 18, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 12px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.35);
  color: #f8faf8;
  font-size: 0.88rem;
  line-height: 1.5;
}
#beginner-panel h2 {
  margin: 0 0 10px;
  font-size: 1rem;
  font-weight: 800;
  color: #fff9c4;
  letter-spacing: 0.02em;
  border-bottom: 2px solid rgba(255, 213, 79, 0.45);
  padding-bottom: 6px;
}
#beginner-panel h3 {
  margin: 12px 0 6px;
  font-size: 0.92rem;
  font-weight: 700;
  color: #e1f5fe;
}
#beginner-panel .guide-block:first-of-type h3 {
  margin-top: 0;
}
#guide-situation {
  margin: 0;
  padding: 8px 10px;
  background: rgba(0, 0, 0, 0.35);
  border-radius: 8px;
  border-left: 4px solid var(--accent);
  font-weight: 600;
  color: #fffef5;
}
#guide-steps {
  margin: 0;
  padding-left: 1.15rem;
}
#guide-steps li {
  margin: 4px 0;
}
#beginner-panel .rules-list {
  margin: 0;
  padding-left: 1.1rem;
}
#beginner-panel .rules-list li {
  margin: 5px 0;
}
/* 用語：details で開閉（アコーディオン風） */
#beginner-panel details.term {
  margin: 4px 0;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.22);
  padding: 2px 8px 6px;
}
#beginner-panel details.term summary {
  cursor: pointer;
  font-weight: 700;
  color: #ffe082;
  list-style-position: outside;
}
#beginner-panel details.term p {
  margin: 6px 0 0;
  font-size: 0.84rem;
  color: #eceff1;
}
@media (max-width: 900px) {
  #game-layout {
    flex-direction: column;
    align-items: stretch;
  }
  #beginner-panel {
    flex: 1 1 auto;
    width: 100%;
    position: relative;
    top: auto;
    max-height: none;
    order: 3;
  }
}

