  // メッセージ更新と同タイミングでガイドも追従（renderAll 外の setMessage も拾う）
  refreshBeginnerPanel();
}

/**
 * 右カラム「今の状況」「次にやること」を state と同じ分岐基準で更新する。
 * renderAll 内の turnLine / ボタン状態と整合させ、長文は #message に任せる。
 */
function refreshBeginnerPanel() {
  const h = state.hands[SEAT_EAST];
  const isHumanTurn = state.phase === 'human_turn';
  const lockedRiichi = state.humanRiichi && state.drawnIndex >= 0;
  const canRiichiBtn = isHumanTurn && !state.humanRiichi && h.length === 14 && canRiichi14(h);

  let situation = '';
  const steps = [];

  if (state.phase === 'ended') {
    if (state.gameOver) {
      situation = 'アガリ成立で局終了。結果を確認できます。';
      steps.push('オーバーレイを閉じる。');
      steps.push('「局をやり直す」で次の一局へ。');
    } else {
      situation = '流局（山切れなど）で局終了。';
      steps.push('「局をやり直す」で牌を配り直す。');
    }
  } else if (state.phase === 'ron_prompt') {
    situation = 'ロン可能：いまの捨て牌で和了形が完成しています。';
    steps.push('「ロン！」で勝利、または「見送る」で次の手番へ。');
    steps.push('迷ったら河に出た牌が自分の手に合うか想像してみる。');
  } else if (state.phase === 'cpu_think') {
    situation = 'CPUの番：' + SEAT_NAMES[state.current] + ' が打牌を選んでいます。';
    steps.push('少し待つ（自動で進みます）。');
    steps.push('各席の河の変化を眺めて次を予想。');
  } else if (isHumanTurn) {
    if (lockedRiichi) {
      situation = 'リーチ宣言済み：この巡はツモ切り（右のツモ牌）のみです。';
      steps.push('右に離れたツモ牌だけをクリックして捨てる。');
    } else {
      situation = 'あなたの番：ツモしたので手牌から1枚捨てます。';
      if (canRiichiBtn) {
        situation += ' リーチ宣言も可能です。';
      }
      steps.push('捨てたい牌を1枚クリック（水色枠は無難なヒント）。');
      if (canRiichiBtn) {
        steps.push('テンパイなら「リーチ」も検討（押したらこの巡は摸切りのみ）。');
      }
      steps.push('リーチしないなら、そのまま好きな牌を切ってOK。');
    }
  } else {
    situation = '待機中：画面の表示が切り替わるまでそのままにしてください。';
    steps.push('状態が変わったらこの欄を読み直す。');
  }

  els.guideSituation.textContent = situation;
  els.guideSteps.innerHTML = steps.map(function (s, i) {
    return '<li>' + s + '</li>';
  }).join('');
}
